write_text("src/main/java/net/mcreator/scpadditions/init/ScpAdditionsModTabs.java", '''package net.mcreator.scpadditions.init;\n\nimport net.minecraftforge.registries.RegistryObject;\nimport net.minecraftforge.registries.DeferredRegister;\nimport net.minecraftforge.fml.common.Mod;\nimport net.minecraftforge.eventbus.api.SubscribeEvent;\nimport net.minecraftforge.event.BuildCreativeModeTabContentsEvent;\n\nimport net.minecraft.world.item.ItemStack;\nimport net.minecraft.world.item.CreativeModeTabs;\nimport net.minecraft.world.item.CreativeModeTab;\nimport net.minecraft.network.chat.Component;\nimport net.minecraft.core.registries.Registries;\n\nimport net.mcreator.scpadditions.ScpAdditionsMod;\nimport net.mcreator.scpadditions.scp012.Scp012Module;\n\nimport java.util.ArrayList;\nimport java.util.List;\n\n@Mod.EventBusSubscriber(bus = Mod.EventBusSubscriber.Bus.MOD)\npublic class ScpAdditionsModTabs {\n    public static final DeferredRegister<CreativeModeTab> REGISTRY =\n            DeferredRegister.create(Registries.CREATIVE_MODE_TAB,\n                    ScpAdditionsMod.MODID);\n\n    public static final RegistryObject<CreativeModeTab> SCP_ADDITIONS =\n            REGISTRY.register("scp_additions", () ->\n                    CreativeModeTab.builder()\n                            .title(Component.translatable(\n                                    "item_group.scp_additions.scp_additions"))\n                            .icon(() -> new ItemStack(\n                                    ScpAdditionsModItems.SECURITY_CREDENTIALS.get()))\n                            .displayItems((parameters, output) ->\n                                    scpAdditionsStacks().forEach(output::accept))\n                            .withSearchBar()\n                            .hideTitle()\n                            .build());\n\n    public static final RegistryObject<CreativeModeTab> SC_PADDITIONS_SC_PS =\n            REGISTRY.register("sc_padditions_sc_ps", () ->\n                    CreativeModeTab.builder()\n                            .title(Component.translatable(\n                                    "item_group.scp_additions.sc_padditions_sc_ps"))\n                            .icon(() -> new ItemStack(Scp012Module.SCP_012_ITEM.get()))\n                            .displayItems((parameters, output) ->\n                                    scpStacks().forEach(output::accept))\n                            .withSearchBar()\n                            .hideTitle()\n                            .build());\n\n    public static List<ItemStack> scpAdditionsStacks() {\n        List<ItemStack> stacks = new ArrayList<>();\n        stacks.add(new ItemStack(ScpAdditionsModItems.SECURITY_CREDENTIALS.get()));\n        stacks.add(new ItemStack(ScpAdditionsModItems.LEVEL_1_KEYCARD.get()));\n        stacks.add(new ItemStack(ScpAdditionsModItems.LEVEL_2_KEYCARD.get()));\n        stacks.add(new ItemStack(ScpAdditionsModItems.LEVEL_3_KEYCARD.get()));\n        stacks.add(new ItemStack(ScpAdditionsModItems.LEVEL_4_KEYCARD.get()));\n        stacks.add(new ItemStack(ScpAdditionsModItems.LEVEL_5_KEYCARD.get()));\n        stacks.add(new ItemStack(ScpAdditionsModItems.LEVEL_6_KEYCARD.get()));\n        stacks.add(new ItemStack(UnifiedReaderItems.SCREWDRIVER.get()));\n        stacks.add(new ItemStack(ScpAdditionsModItems.HAZMAT_SUIT.get()));\n        stacks.add(new ItemStack(ScpAdditionsModItems.PLAYING_CARD.get()));\n        stacks.add(new ItemStack(ScpAdditionsModItems.CREDIT_CARD.get()));\n        stacks.add(new ItemStack(ScpAdditionsModItems.PIECES_OF_PAPER.get()));\n        stacks.add(new ItemStack(ScpAdditionsModItems.COIN.get()));\n        stacks.add(new ItemStack(ScpAdditionsModItems.EMPTY_CUP.get()));\n        return stacks;\n    }\n\n    public static List<ItemStack> scpStacks() {\n        List<ItemStack> stacks = new ArrayList<>();\n        stacks.add(new ItemStack(Scp012Module.SCP_012_ITEM.get()));\n        stacks.add(new ItemStack(ScpAdditionsModBlocks.SCP_079ON.get()));\n        stacks.add(new ItemStack(Scp131Items.SCP_106_SPAWN_EGG.get()));\n        stacks.add(new ItemStack(Scp131Items.SCP_131_A_SPAWN_EGG.get()));\n        stacks.add(new ItemStack(Scp131Items.SCP_131_B_SPAWN_EGG.get()));\n        stacks.add(new ItemStack(Scp131Items.SCP_173_SPAWN_EGG.get()));\n        stacks.add(new ItemStack(ScpAdditionsModBlocks.SCP_294.get()));\n        stacks.add(new ItemStack(ScpAdditionsModBlocks.SCP_330.get()));\n        stacks.add(new ItemStack(ScpAdditionsModBlocks.SCP_426.get()));\n        stacks.add(new ItemStack(ScpAdditionsModItems.SCP_572.get()));\n        stacks.add(new ItemStack(Scp714Items.SCP_714.get()));\n        stacks.add(new ItemStack(ScpAdditionsModBlocks.SCP_902_CLOSED.get()));\n        stacks.add(new ItemStack(ScpAdditionsModItems.SCP_914_ASSEMBLY_KIT.get()));\n        stacks.add(new ItemStack(ScpAdditionsModBlocks.SCP_914BLOCK.get()));\n        stacks.add(new ItemStack(ScpAdditionsModBlocks.SCP_914CLOCKWORKS.get()));\n        stacks.add(new ItemStack(ScpAdditionsModBlocks.SCP_914BODY.get()));\n        stacks.add(new ItemStack(ScpAdditionsModBlocks.SCP_914DIAL_1TO_1.get()));\n        stacks.add(new ItemStack(ScpAdditionsModBlocks.SCP_914_KEY_WIND.get()));\n        stacks.add(new ItemStack(ScpAdditionsModBlocks.SCP_914_INTAKE.get()));\n        stacks.add(new ItemStack(ScpAdditionsModBlocks.SCP_914_OUTPUT.get()));\n        stacks.add(new ItemStack(ScpAdditionsModBlocks.SCP_914_INTAKE_DOOR.get()));\n        stacks.add(new ItemStack(ScpAdditionsModBlocks.SCP_914_OUTPUT_DOOR.get()));\n        stacks.add(new ItemStack(ScpAdditionsModBlocks.SCP_1176.get()));\n        return stacks;\n    }\n\n    @SubscribeEvent\n    public static void buildTabContentsVanilla(\n            BuildCreativeModeTabContentsEvent tabData) {\n        if (tabData.getTabKey() == CreativeModeTabs.FOOD_AND_DRINKS) {\n            tabData.accept(ScpAdditionsModItems.SCP_330_RED_CANDY.get());\n            tabData.accept(ScpAdditionsModItems.SCP_330_GREEN_CANDY.get());\n            tabData.accept(ScpAdditionsModItems.SCP_330_YELLOW_CANDY.get());\n            tabData.accept(ScpAdditionsModItems.SCP_330_BLUE_CANDY.get());\n            tabData.accept(ScpAdditionsModItems.SCP_1176HONEY.get());\n        }\n    }\n}\n''')

write_text("src/main/java/net/mcreator/scpadditions/client/CreativeTabPresentation.java", '''package net.mcreator.scpadditions.client;\n\nimport net.minecraft.client.Minecraft;\nimport net.minecraft.client.gui.Font;\nimport net.minecraft.client.gui.GuiGraphics;\nimport net.minecraft.client.gui.screens.inventory.CreativeModeInventoryScreen;\nimport net.minecraft.network.chat.Component;\nimport net.minecraft.world.item.CreativeModeTab;\nimport net.minecraft.world.item.ItemStack;\nimport net.minecraftforge.api.distmarker.Dist;\nimport net.minecraftforge.client.event.ScreenEvent;\nimport net.minecraftforge.eventbus.api.SubscribeEvent;\nimport net.minecraftforge.fml.common.Mod;\nimport net.mcreator.scpadditions.ScpAdditionsMod;\nimport net.mcreator.scpadditions.facility.FacilityModule;\nimport net.mcreator.scpadditions.init.ScpAdditionsModTabs;\n\nimport java.util.List;\n\n@Mod.EventBusSubscriber(modid = ScpAdditionsMod.MODID,\n        bus = Mod.EventBusSubscriber.Bus.FORGE, value = Dist.CLIENT)\npublic final class CreativeTabPresentation {\n    private static final long ICON_DISPLAY_MILLIS = 900L;\n    private static final int HEADER_WIDTH = 162;\n    private static final int HEADER_HEIGHT = 18;\n    private static final int TITLE_MAX_WIDTH = 70;\n\n    private static long lastIconStep = Long.MIN_VALUE;\n\n    private CreativeTabPresentation() {\n    }\n\n    @SubscribeEvent\n    public static void beforeRender(ScreenEvent.Render.Pre event) {\n        if (!(event.getScreen() instanceof CreativeModeInventoryScreen screen)) return;\n\n        updateTabIcons();\n        if (CreativeModeInventoryScreen.selectedTab ==\n                FacilityModule.SCP_FACILITY_BLOCKS.get()\n                && screen.searchBox.getValue().isEmpty()) {\n            ensureFacilitySectionLayout(screen);\n        }\n    }\n\n    @SubscribeEvent\n    public static void afterRender(ScreenEvent.Render.Post event) {\n        if (!(event.getScreen() instanceof CreativeModeInventoryScreen screen)) return;\n\n        CreativeModeTab selected = CreativeModeInventoryScreen.selectedTab;\n        if (isScpAdditionsTab(selected)) {\n            renderCompactTitle(screen, event.getGuiGraphics(), selected.getDisplayName());\n        }\n\n        if (selected == FacilityModule.SCP_FACILITY_BLOCKS.get()\n                && screen.searchBox.getValue().isEmpty()) {\n            renderFacilityHeaders(screen, event.getGuiGraphics());\n        }\n    }\n\n    private static void updateTabIcons() {\n        long step = System.currentTimeMillis() / ICON_DISPLAY_MILLIS;\n        if (step == lastIconStep) return;\n        lastIconStep = step;\n\n        setIcon(ScpAdditionsModTabs.SCP_ADDITIONS.get(),\n                ScpAdditionsModTabs.scpAdditionsStacks(), step);\n        setIcon(ScpAdditionsModTabs.SC_PADDITIONS_SC_PS.get(),\n                ScpAdditionsModTabs.scpStacks(), step);\n        setIcon(FacilityModule.SCP_FACILITY_BLOCKS.get(),\n                FacilityModule.creativeTabIconStacks(), step);\n    }\n\n    private static void setIcon(CreativeModeTab tab, List<ItemStack> stacks, long step) {\n        if (stacks.isEmpty()) return;\n        int index = Math.floorMod(step, stacks.size());\n        tab.iconItemStack = stacks.get(index).copy();\n    }\n\n    private static void ensureFacilitySectionLayout(\n            CreativeModeInventoryScreen screen) {\n        List<ItemStack> layout = FacilityModule.creativeTabDisplayStacks();\n        List<ItemStack> current = screen.getMenu().items;\n        if (hasSectionLayout(current, layout.size())) return;\n\n        current.clear();\n        layout.forEach(stack -> current.add(stack.copy()));\n        screen.scrollOffs = 0.0F;\n        screen.getMenu().scrollTo(0.0F);\n    }\n\n    private static boolean hasSectionLayout(List<ItemStack> items, int expectedSize) {\n        if (items.size() != expectedSize || items.size() < 9) return false;\n        for (int i = 0; i < 9; i++) {\n            if (!items.get(i).isEmpty()) return false;\n        }\n        return true;\n    }\n\n    private static void renderFacilityHeaders(CreativeModeInventoryScreen screen,\n            GuiGraphics graphics) {\n        int currentRow = rowIndexForScroll(screen.scrollOffs,\n                screen.getMenu().items.size());\n        int sectionRow = 0;\n        int left = screen.getGuiLeft() + 8;\n        int top = screen.getGuiTop() + 17;\n        Font font = Minecraft.getInstance().font;\n\n        for (FacilityModule.CreativeSection section :\n                FacilityModule.creativeSections()) {\n            int visibleRow = sectionRow - currentRow;\n            if (visibleRow >= 0 && visibleRow < 5) {\n                int y = top + visibleRow * HEADER_HEIGHT;\n                graphics.blitSprite(section.sprite(), left, y,\n                        HEADER_WIDTH, HEADER_HEIGHT);\n                graphics.drawString(font,\n                        Component.translatable(section.translationKey()),\n                        left + 5, y + 5, section.textColor(), false);\n            }\n            sectionRow += 1 + Math.max(1,\n                    (section.items().size() + 8) / 9);\n        }\n    }\n\n    private static int rowIndexForScroll(float scroll, int itemCount) {\n        int totalRows = (itemCount + 8) / 9;\n        int scrollableRows = Math.max(totalRows - 5, 0);\n        return Math.max((int) (scroll * scrollableRows + 0.5F), 0);\n    }\n\n    private static void renderCompactTitle(CreativeModeInventoryScreen screen,\n            GuiGraphics graphics, Component title) {\n        Font font = Minecraft.getInstance().font;\n        int width = Math.max(font.width(title), 1);\n        float scale = Math.min(1.0F, TITLE_MAX_WIDTH / (float) width);\n\n        graphics.pose().pushPose();\n        graphics.pose().translate(screen.getGuiLeft() + 8,\n                screen.getGuiTop() + 6, 300.0F);\n        graphics.pose().scale(scale, scale, 1.0F);\n        graphics.drawString(font, title, 0, 0, 0x404040, false);\n        graphics.pose().popPose();\n    }\n\n    private static boolean isScpAdditionsTab(CreativeModeTab tab) {\n        return tab == ScpAdditionsModTabs.SCP_ADDITIONS.get()\n                || tab == ScpAdditionsModTabs.SC_PADDITIONS_SC_PS.get()\n                || tab == FacilityModule.SCP_FACILITY_BLOCKS.get();\n    }\n}\n''')

